create table if not exists settings(k text primary key,v text default '');
create table if not exists members(id text primary key,name text not null,mobile text default '',email text default '',role text default 'सदस्य',area text default '',address text default '',photo text default '',created_at timestamptz default now());
create table if not exists receipts(id text primary key,name text not null,mobile text default '',address text default '',amount numeric not null,payment text default 'रोख',note text default '',created_at timestamptz default now());
create table if not exists aarti(id bigint generated by default as identity primary key,date date not null,time text default '',member_id text default '',member_name text default '',notes text default '');
create table if not exists notifications(id bigint generated by default as identity primary key,title text not null,message text not null,created_at timestamptz default now());
insert into settings(k,v) values('upi',''),('contact',''),('address','') on conflict(k) do nothing;